// ===================================================================
// SQL: el closer marcó el lead como calificado en crm.oacg.cl (Twenty).
// Es una conversión OFFLINE: Meta la castea por email/teléfono hasheados
// (action_source "system_generated"), no por cookie de navegador.
//
// El payload de Twenty cambia según la versión y el objeto que dispare el
// webhook, así que las claves se buscan en profundidad en vez de asumir
// una ruta fija.
// ===================================================================
const crypto = require('crypto');
const hash = (v) => (v ? crypto.createHash('sha256').update(String(v).trim().toLowerCase()).digest('hex') : '');

// Valor de un SQL. Si algún día cambia, se toca acá y en ningún otro lado.
const VALOR_SQL = 100;
const MONEDA = 'USD';

// Etapas del pipeline que cuentan como SQL (comparación EXACTA, sin
// acentos y en minúsculas). El pipeline tiene además Nuevo, MQL y
// PQL · No contesta, que no disparan nada.
const ETAPAS_SQL = ['sql', 'sql+'];

function norm(s) {
  return String(s == null ? '' : s)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function deepFind(obj, claves, validar) {
  const objetivo = claves.map(norm);
  const visto = new Set();
  const cola = [obj];
  while (cola.length) {
    const cur = cola.shift();
    if (!cur || typeof cur !== 'object' || visto.has(cur)) continue;
    visto.add(cur);
    for (const k of Object.keys(cur)) {
      const v = cur[k];
      if (v && typeof v === 'object') { cola.push(v); continue; }
      if (!objetivo.includes(norm(k))) continue;
      const s = String(v == null ? '' : v).trim();
      if (!s) continue;
      if (validar && !validar(s)) continue;
      return s;
    }
  }
  return '';
}

const wh = $json || {};
const body = wh.body || wh;
const headers = wh.headers || {};

const email = deepFind(body, ['email', 'primaryemail', 'emails', 'correo'], function (s) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s); }).toLowerCase();
const telefonoRaw = deepFind(body, ['phone', 'primaryphonenumber', 'telefono', 'celular', 'whatsapp']);
const telefono = String(telefonoRaw).replace(/\D/g, '');
const nombre = deepFind(body, ['name', 'nombre', 'firstname', 'fullname']);
const apellido = deepFind(body, ['lastname', 'apellido']);
const etapa = deepFind(body, ['stage', 'etapa', 'status', 'estado', 'pipelinestage', 'dealstage']);
const recordId = deepFind(body, ['id', 'recordid', 'opportunityid']);
// Si el lead trae los identificadores de Meta guardados desde la landing,
// se aprovechan: suben mucho la calidad del match.
const fbc = deepFind(body, ['fbc', 'metafbc', 'fbclid']);
const fbp = deepFind(body, ['fbp', 'metafbp']);

if (!email && telefono.length < 10) {
  return [{ json: { ok: false, motivo: 'sin_email_ni_telefono', payload: body } }];
}

const etapaNorm = norm(etapa);
const esSql = ETAPAS_SQL.indexOf(etapaNorm) !== -1;
if (!esSql) {
  // Otro cambio en el CRM: no es un SQL, no se manda nada.
  return [{ json: { ok: false, motivo: 'etapa_no_sql', etapa: etapa, payload: body } }];
}

// Anti-duplicado: si el closer mueve el registro de etapa varias veces,
// el SQL se cuenta una sola vez por lead.
const estado = $getWorkflowStaticData('global');
estado.sql = estado.sql || {};
const clave = recordId || hash(email || telefono);
const ahora = Date.now();
for (const k of Object.keys(estado.sql)) {
  if (ahora - estado.sql[k] > 90 * 86400000) delete estado.sql[k];
}
if (estado.sql[clave]) {
  return [{ json: { ok: false, motivo: 'sql_ya_enviado', clave: clave } }];
}
estado.sql[clave] = ahora;

const eventTime = Math.floor(Date.now() / 1000);
const eventId = 'sql_' + clave;

let country = 'CL';
const PREFIJOS = [['595','PY'],['593','EC'],['507','PA'],['506','CR'],['56','CL'],['54','AR'],['52','MX'],['51','PE'],['34','ES'],['1','US']];
for (const par of PREFIJOS) { if (telefono.indexOf(par[0]) === 0) { country = par[1]; break; } }

const emailHash = hash(email || telefono);

const ga4Body = {
  client_id: String((parseInt(emailHash.slice(0, 12), 16) % 1e10) + '.' + eventTime),
  user_id: emailHash,
  timestamp_micros: eventTime * 1000000,
  non_personalized_ads: false,
  events: [{
    name: 'sql',
    params: {
      currency: MONEDA,
      value: VALOR_SQL,
      session_id: String(eventTime),
      engagement_time_msec: 100,
      event_source: 'crm_twenty',
      crm_stage: String(etapa),
      items: [{
        item_id: 'clinera_sql_calificado',
        item_name: 'Clinera SQL - Lead calificado por closer',
        item_category: 'crm',
        price: VALOR_SQL,
        quantity: 1,
      }],
    },
  }],
};

return [{ json: {
  ok: true,
  em: hash(email),
  ph: hash(telefono),
  fn: hash(nombre),
  ln: hash(apellido),
  country_hashed: hash(country),
  external_id: hash(email || telefono),
  fbc: fbc,
  fbp: fbp,
  client_user_agent: String(headers['user-agent'] || ''),
  event_time: eventTime,
  event_id: eventId,
  value: VALOR_SQL,
  currency: MONEDA,
  country: country,
  etapa: String(etapa),
  record_id: String(recordId || ''),
  ga4Body: ga4Body,
} }];
